import{_ as o,o as t,c as e,a2 as i}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"🚗 02 · 自动驾驶（Autonomous Driving）","description":"","frontmatter":{},"headers":[],"relativePath":"05-算法岗-前沿与具身/02-自动驾驶.md","filePath":"05-算法岗-前沿与具身/02-自动驾驶.md","lastUpdated":1786806808000}'),r={name:"05-算法岗-前沿与具身/02-自动驾驶.md"};function n(l,a,s,c,d,u){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="🚗-02-·-自动驾驶-autonomous-driving" tabindex="-1">🚗 02 · 自动驾驶（Autonomous Driving） <a class="header-anchor" href="#🚗-02-·-自动驾驶-autonomous-driving" aria-label="Permalink to &quot;🚗 02 · 自动驾驶（Autonomous Driving）&quot;">​</a></h1><blockquote><p>最早大规模落地的「具身/机器人」系统之一。算法岗中岗位稳定、工程深、数据闭环要求高。</p></blockquote><hr><h2 id="一、系统分层" tabindex="-1">一、系统分层 <a class="header-anchor" href="#一、系统分层" aria-label="Permalink to &quot;一、系统分层&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>感知(Perception) → 预测(Prediction) → 规划(Planning) → 控制(Control)</span></span></code></pre></div><ul><li><strong>感知</strong>：检测（车辆/行人）、分割、车道线、BEV（鸟瞰图）感知、多传感器融合（相机/LiDAR/Radar）</li><li><strong>预测</strong>：行人与车辆轨迹预测</li><li><strong>规划</strong>：路径与行为决策（规则 / RL / 学习）</li><li><strong>控制</strong>：转向/加速/制动执行</li></ul><h2 id="二、两条技术路线" tabindex="-1">二、两条技术路线 <a class="header-anchor" href="#二、两条技术路线" aria-label="Permalink to &quot;二、两条技术路线&quot;">​</a></h2><ul><li><strong>模块化（传统）</strong>：各模块独立优化，可解释、易调试，但模块误差累积。</li><li><strong>端到端（End-to-End）</strong>：感知→控制直接学（输入传感器，输出控制），代表 UniAD、Tesla 路线。潜力大但可解释/安全验证难。</li></ul><h2 id="三、数据闭环-关键竞争壁垒" tabindex="-1">三、数据闭环（关键竞争壁垒） <a class="header-anchor" href="#三、数据闭环-关键竞争壁垒" aria-label="Permalink to &quot;三、数据闭环（关键竞争壁垒）&quot;">​</a></h2><ul><li>采集 → 自动标注 → 挖掘难例（长尾场景）→ 训练 → 影子模式验证 → OTA 迭代</li><li>长尾 corner case（罕见场景）是落地的核心难点</li></ul><h2 id="四、大模型赋能" tabindex="-1">四、大模型赋能 <a class="header-anchor" href="#四、大模型赋能" aria-label="Permalink to &quot;四、大模型赋能&quot;">​</a></h2><ul><li>用 LLM/VLM 做「场景理解」「自然语言交互」「仿真生成」</li><li>世界模型用于仿真与预测</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：端到端自动驾驶的利弊？</strong></p><blockquote><p>利：信息无损传递、潜力上限高；弊：可解释差、安全难验证、调试难、数据需求大。传统模块化更可控，当前量产多用混合。</p></blockquote><p><strong>Q2：自动驾驶最大的技术难点？</strong></p><blockquote><p>长尾 corner case（罕见危险场景）的数据与处理能力；感知在恶劣天气/遮挡下的鲁棒性；规划在复杂交互中的决策安全。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-世界模型">03-世界模型</a></p>',19)])])}const g=o(r,[["render",n]]);export{p as __pageData,g as default};
